Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include<bits/stdc++.h>
using namespace std;
const int N=505;
typedef long long ll;
int n,m,mod;
int C[N][N];
int f[N],g[N],ff[N][N],gg[N][N];
inline void add(int &x,int y){
	x+=y;if(x>=mod) x-=mod;
}
int main(){
	scanf("%d%d%d",&n,&m,&mod);
	for(int i=0;i<=n;i++){
		C[i][0]=1;
		for(int j=1;j<=i;j++)
			C[i][j]=(C[i-1][j]+C[i-1][j-1])%mod;
	}
	f[0]=1;
	for(int i=1;i<=n;i++)
		for(int j=1;j<=i;j++){
			add(f[i],1ll*f[j-1]*f[i-j]%mod*C[i-1][j-1]%mod*(i+1)%mod);
			add(g[i],1ll*g[j-1]*f[i-j]%mod*C[i-1][j-1]%mod*(i+1)%mod);
			add(g[i],1ll*g[i-j]*f[j-1]%mod*C[i-1][j-1]%mod*(i+1)%mod);
			int s=0;for(int k=1;k<=i;k++) add(s,abs(k-j));
			add(g[i],1ll*f[j-1]*f[i-j]%mod*C[i-1][j-1]%mod*s%mod);
		}
	ff[0][0]=1;
	for(int i=1;i<=n;i++)
		for(int j=0;j<=i;j++){
			if(j==i) {
				ff[i][j]=f[i],gg[i][j]=g[i];
				break;
			}
			ff[i][j]=ff[i-1][j];gg[i][j]=gg[i-1][j];
			for(int k=1;k<=j;k++){
				add(ff[i][j],1ll*ff[i-k-1][j-k]*f[k]%mod*C[j][k]%mod);
				add(gg[i][j],1ll*ff[i-k-1][j-k]*g[k]%mod*C[j][k]%mod);
				add(gg[i][j],1ll*gg[i-k-1][j-k]*f[k]%mod*C[j][k]%mod);
			}
		}
	printf("%d",gg[n][m]);
	return 0;
}
